  code+=f"p=importlib.import_module({package!r});r=Path(m.distribution({distribution!r}).locate_file({package!r})).resolve()\nif not r.is_relative_to(expected) or not Path(p.__file__).resolve().is_relative_to(r):raise RuntimeError('Wrong copied package origin')\nroots[{package!r}]=str(r)\n"
 code+="print(json.dumps({'prefix':sys.prefix,'interpreter':sys.executable,'roots':roots}))\n";r=run(label,[str(copy/'bin/python'),'-I','-B',*(['-O'] if optimized else []),'-c',code]);return json.loads(r['output'])['roots']
def write(path,content,mode=None):
 previous=stat.S_IMODE(path.stat().st_mode) if path.exists() else 0o644
 if path.exists():path.chmod(previous|0o200)
 path.write_bytes(content);path.chmod(previous if mode is None else mode)
