  elif kind=='data':target=package/'unexpected.txt';target.write_text('extra\n');reason='Installed source/data inventory differs from Git'
  elif kind=='empty-directory':target=package/'empty-control';target.mkdir();reason='Installed source/data inventory differs from Git'
  elif kind=='bytecode':target=package/'__pycache__';target.mkdir();(target/'control.pyc').write_bytes(b'bad-bytecode');reason='Installed source/data inventory differs from Git'
  elif kind=='symlink':target=package/'linked-control';target.symlink_to(outside/'external.py');reason='Installed package contains a symlink'
  elif kind=='fifo':target=package/'pipe-control';os.mkfifo(target);reason='Unsupported installed package member type'
